function ns.CreatureInfo.Get(npcID)
	local packed = ns.CreatureInfo.entries[npcID]
	if not packed then
		return nil
	end
	local displayID = math.floor(packed / 268435456)
	local metadata = packed % 268435456
	local iconIndex = math.floor(metadata / 1048576)
	local creature = metadata % 1048576
	return math.floor(creature / 65536),
		creature % 65536,
		ns.CreatureInfo.icons[iconIndex],
		displayID > 0 and displayID or nil
end
